function publicResourceType(resource) {
    return resource
        ? {
            id: resource.id,
            label: resource.label,
            subtitle: resource.subtitle,
            name: resource.label,
            root: resource.root,
            path: resource.hubPath,
            hubPath: resource.hubPath,
            image: resource.image,
            icon: resource.icon,
            contextKind: "resource",
            resourceType: resource.id,
